import { test, expect } from '@playwright/test';

test.describe('Faceted Search Without Page Reload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/search');
    // Wait for search results to load
    await page.waitForLoadState('networkidle');
  });

  test('should update search results when selecting a facet filter', async ({ page }) => {
    // Get initial result count
    const initialResults = await page.getByRole('region', { name: /search results/i }).locator('[data-testid="result-item"]').count();
    expect(initialResults).toBeGreaterThan(0);

    // Get the page URL before filter application
    const urlBefore = page.url();

    // Click on a facet filter (e.g., category filter)
    const categoryFilter = page.getByRole('button', { name: /electronics/i });
    await categoryFilter.click();

    // Wait for results to update without full page reload
    await page.waitForLoadState('networkidle');

    // Verify URL changed (indicating filter was applied)
    const urlAfter = page.url();
    expect(urlAfter).not.toBe(urlBefore);

    // Verify results were updated
    const updatedResults = await page.getByRole('region', { name: /search results/i }).locator('[data-testid="result-item"]').count();
    expect(updatedResults).toBeGreaterThan(0);

    // Verify the filter is visually selected
    await expect(categoryFilter).toHaveAttribute('aria-pressed', 'true');
  });

  test('should update results when selecting multiple facet filters', async ({ page }) => {
    // Select first facet filter
    const priceFilter = page.getByRole('button', { name: /under \$100/i });
    await priceFilter.click();
    await page.waitForLoadState('networkidle');

    // Verify first filter is applied
    await expect(priceFilter).toHaveAttribute('aria-pressed', 'true');

    // Get results after first filter
    const resultsAfterFirstFilter = await page.getByRole('region', { name: /search results/i }).locator('[data-testid="result-item"]').count();

    // Select second facet filter
    const brandFilter = page.getByRole('button', { name: /brand: samsung/i });
    await brandFilter.click();
    await page.waitForLoadState('networkidle');

    // Verify both filters are applied
    await expect(priceFilter).toHaveAttribute('aria-pressed', 'true');
    await expect(brandFilter).toHaveAttribute('aria-pressed', 'true');

    // Verify results were updated again
    const resultsAfterSecondFilter = await page.getByRole('region', { name: /search results/i }).locator('[data-testid="result-item"]').count();
    expect(resultsAfterSecondFilter).toBeLessThanOrEqual(resultsAfterFirstFilter);
  });

  test('should remove filter and update results when deselecting a facet', async ({ page }) => {
    // Select a facet filter
    const colorFilter = page.getByRole('button', { name: /color: blue/i });
    await colorFilter.click();
    await page.waitForLoadState('networkidle');

    // Verify filter is applied
    await expect(colorFilter).toHaveAttribute('aria-pressed', 'true');

    const resultsWithFilter = await page.getByRole('region', { name: /search results/i }).locator('[data-testid="result-item"]').count();

    // Deselect the filter
    await colorFilter.click();
    await page.waitForLoadState('networkidle');

    // Verify filter is removed
    await expect(colorFilter).toHaveAttribute('aria-pressed', 'false');

    // Verify results were updated
    const resultsWithoutFilter = await page.getByRole('region', { name: /search results/i }).locator('[data-testid="result-item"]').count();
    expect(resultsWithoutFilter).toBeGreaterThanOrEqual(resultsWithFilter);
  });

  test('should display loading state while updating results', async ({ page }) => {
    // Click on a facet filter
    const sizeFilter = page.getByRole('button', { name: /size: large/i });
    await sizeFilter.click();

    // Check for loading indicator
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Wait for results to update
    await page.waitForLoadState('networkidle');

    // Verify loading indicator is gone
    await expect(loadingIndicator).not.toBeVisible();

    // Verify results are displayed
    const results = page.getByRole('region', { name: /search results/i });
    await expect(results).toBeVisible();
  });

  test('should maintain scroll position when updating faceted search results', async ({ page }) => {
    // Scroll down to view more results
    await page.getByRole('region', { name: /search results/i }).scrollIntoViewIfNeeded();
    const scrollPositionBefore = await page.evaluate(() => window.scrollY);

    // Apply a facet filter
    const typeFilter = page.getByRole('button', { name: /type: laptop/i });
    await typeFilter.click();
    await page.waitForLoadState('networkidle');

    // Check scroll position after filter application
    const scrollPositionAfter = await page.evaluate(() => window.scrollY);

    // Scroll position should be maintained or close to original
    expect(Math.abs(scrollPositionAfter - scrollPositionBefore)).toBeLessThan(100);
  });
});
